package expo.modules.zenremotedesktop.moonlight

import org.junit.Assert.assertEquals
import org.junit.Test
import java.nio.file.Files
import java.util.Base64

/**
 * Production signer contract: the actual [MoonlightEnrollmentSigner] used by
 * the Expo module must produce the exact signature the Go verifier
 * (sunshine_enroll_vector_test.go) accepts for the shared vector.
 */
class MoonlightEnrollmentSignerTest {

  @Test
  fun productionSignerMatchesGoVerifierVector() {
    val dir = Files.createTempDirectory("zen-enrollment-identity").toFile()
    Files.write(dir.toPath().resolve("client.key"), Base64.getDecoder().decode(PKCS8_B64))
    Files.write(
      dir.toPath().resolve("client.crt"),
      ("-----BEGIN CERTIFICATE-----\n" + CERT_DER_B64 + "\n-----END CERTIFICATE-----\n")
        .toByteArray(Charsets.US_ASCII),
    )
    assertEquals(EXPECTED_SIGNATURE_HEX, MoonlightEnrollmentSigner.sign(dir, ATTEMPT, NONCE))
    assertEquals(CERT_FINGERPRINT, MoonlightEnrollmentSigner.fingerprint(dir))
  }

  private companion object {
    const val PKCS8_B64 = ""
    const val CERT_DER_B64 = ""
    const val ATTEMPT = "00ff00ff00ff00ff00ff00ff00ff00ff"
    const val NONCE = "11223344556677889900aabbccddeeff11223344556677889900aabbccddeeff"
    const val EXPECTED_SIGNATURE_HEX = ""
    const val CERT_FINGERPRINT = "38f7a797ccd615e23a1c7ba1865b3b8942c26bc49693d064b509fd246c6a5990"
  }
}
